#!/bin/bash #exit 1 - skript nie je spusteny ako root alebo sudo #exit 2 - chyba pri instalacii nginx #exit 3 - chyba pri instalacii mariadb #exit 4 - chyba pri instalacii php #exit 5 - chyba pri pridani systemoveho admina #exit 6 - chyba pri pridani web usera #exit 7 - chyba pri odstraneni web usera #exit 8 - chyba pri odstraneni web usera #exit 9 - chyba pri odstraneni systemoveho admina RED="\e[31m" GREEN="\e[32m" ENDCOLOR="\e[0m" # Tento script je na instalaciu nginx, mariadb, php na Raspbrrry Pi OS # kontrola ci je spusteny ako root alebo sudo if [ $EUID -eq 0 ]; then echo -e "${GREEN}Skript spusteny ako root alebo sudo${ENDCOLOR}" else echo -e "${RED}Skript musi byt spusteny ako root alebo sudo${ENDCOLOR}" exit 1 fi function system_update { echo -e "${GREEN}Aktualizacia systemu${ENDCOLOR}" sudo apt-get update -y sudo apt-get upgrade -y } function install_nginx { echo -e "${GREEN}Instalacia nginx${ENDCOLOR}" sudo apt-get install nginx -y if [ ! -f /etc/skel/index.html ]; then wget https://haste.misike.eu/raw/serowuyoba -P /etc/skel/ mv /etc/skel/serowuyoba /etc/skel/index.html fi VYSLEDOK=$? if [ $VYSLEDOK -eq 0 ]; then echo -e "${GREEN}Nginx je nainstalovany${ENDCOLOR}" else echo -e "${RED}Chyba pri instalacii nginx${ENDCOLOR}" exit 2 fi } function install_mariadb { echo -e "${GREEN}Instalacia mariadb${ENDCOLOR}" sudo apt-get install mariadb-server -y VYSLEDOK=$? if [ $VYSLEDOK -eq 0 ]; then echo -e "${GREEN}Mariadb je nainstalovany${ENDCOLOR}" else echo -e "${RED}Chyba pri instalacii mariadb${ENDCOLOR}" exit 3 fi } function install_php { echo -e "${GREEN}Instalacia php${ENDCOLOR}" sudo apt-get install php -y VYSLEDOK=$? if [ $(dpkg -l | grep -c apache2) -gt 0 ]; then systemctl disable apache2 sudo apt-get purge apache2 apache2-utils apache2.2-bin apache2-common -y sudo rm /var/www/html/index.html fi if [ $VYSLEDOK -eq 0 ]; then echo -e "${GREEN}php je nainstalovany${ENDCOLOR}" else echo -e "${RED}Chyba pri instalacii php${ENDCOLOR}" exit 4 fi } function add_system_admin { echo -e "${GREEN}Pridanie systemoveho admina${ENDCOLOR}" sudo adduser sysadmin sudo usermod -aG sudo sysadmin VYSLEDOK=$? if [ $VYSLEDOK -eq 0 ]; then echo -e "${GREEN}Systemovy admin je pridany${ENDCOLOR}" else echo -e "${RED}Chyba pri pridani systemoveho admina${ENDCOLOR}" exit 5 fi } function add_web_user { echo -e "${GREEN}Pridanie web pouzivatela${ENDCOLOR}" read -p "Zadaj meno web pouzivatela: " meno sudo adduser --home /var/www/html/"$meno" "$meno" VYSLEDOK=$? if [ $VYSLEDOK -eq 0 ]; then echo -e "${GREEN}Web pouzivatel je pridany${ENDCOLOR}" else echo -e "${RED}Chyba pri pridani web pouzivatela${ENDCOLOR}" exit 6 fi } function remove_web_user { echo -e "${GREEN}Odstranenie web pouzivatela${ENDCOLOR}" read -p "Zadaj meno web pouzivatela: " meno read -p "Zadaj ci chces odstranit aj home adresar web pouzivatela (y/n): " home if [[ "$home" == "y" ]]; then sudo rm -r /var/www/html/"$meno" sudo deluser "$meno" elif [ "$home" == "n" ]; then sudo deluser "$meno" else echo "Zadaj y alebo n" exit 7 fi VYSLEDOK=$? if [[ $VYSLEDOK -eq 0 ]]; then echo -e "${GREEN}Web pouzivatel je odstraneny${ENDCOLOR}" else echo -e "${RED}Chyba pri odstraneni web pouzivatela${ENDCOLOR}" exit 8 fi } function remove_system_admin { echo -e "${GREEN}Odstranenie systemoveho admina${ENDCOLOR}" if [[ "$(id sysadmin | grep -c "sysadmin")" -ge 1 ]]; then sudo deluser sysadmin echo -e "${GREEN}Systemovy admin je odstraneny${ENDCOLOR}" else echo -e "${RED}Systemovy admin neexistuje${ENDCOLOR}" exit 9 fi } function uninstall_all { echo -e "${GREEN}Odinstalovanie nginx, mariadb, php${ENDCOLOR}" sudo apt-get purge nginx nginx-common nginx-core 'mariadb-*' 'php*' libapache2-mod-php7.4 -y sudo apt-get autoremove -y } function uninstall_nginx() { echo -e "${GREEN}Odinstalovanie nginx${ENDCOLOR}" sudo apt purge nginx nginx-common nginx-core -y sudo apt-get autoremove -y } function uninstall_mariadb() { echo -e "${GREEN}Odinstalovanie mariadb${ENDCOLOR}" sudo apt-get purge 'mariadb-*' -y sudo apt-get autoremove -y } function uninstall_php() { echo -e "${GREEN}Odinstalovanie php${ENDCOLOR}" sudo apt-get purge 'php*' libapache2-mod-php7.4 -y sudo apt-get autoremove -y } function menu { zrus=0 while [ $zrus -ne 1 ]; do if [[ "$(dpkg -l | grep -c nginx)" -gt 0 && "$(dpkg -l | grep -c mariadb-server)" -gt 0 && "$(dpkg -l | grep -c mariadb-server)" -gt 0 ]]; then echo "1. Odinstalovanie nginx, mariadb, php" echo "2. Pridanie systemoveho admina" echo "3. Pridanie web usera" echo "4. Odstranenie systemoveho admina" echo "5. Odstranenie web usera" echo "6. Koniec" read -p "Zadaj cislo: " cislo case $cislo in 1) uninstall_all;; 2) add_system_admin ;; 3) add_web_user ;; 4) remove_system_admin ;; 5) remove_web_user ;; 6) zrus=1 ;; *) echo "Zadaj cislo od 1 do 6" ;; esac elif [[ "$(dpkg -l | grep -c nginx)" -gt 0 && "$(dpkg -l | grep -c mariadb-server)" -gt 0 ]]; then echo "1. Odinstalovanie nginx, mariadb" echo "2. Nainstalovanie php" echo "3. Pridanie systemoveho admina" echo "4. Pridanie web usera" echo "5. Odstranenie systemoveho admina" echo "6. Odstranenie web usera" echo "7. Koniec" read -p "Zadaj cislo: " cislo case $cislo in 1) uninstall_nginx uninstall_mariadb;; 2) install_php ;; 3) add_system_admin ;; 4) add_web_user ;; 5) remove_system_admin ;; 6) remove_web_user ;; 7) zrus=1;; *) echo "Zadaj cislo od 1 do 7" ;; esac elif [[ "$(dpkg -l | grep -c nginx)" -gt 0 && "$(dpkg -l | grep -c php)" -gt 0 ]]; then echo "1. Odinstalovanie nginx, php" echo "2. Nainstalovanie mariadb" echo "3. Pridanie systemoveho admina" echo "4. Pridanie web usera" echo "5. Odstranenie systemoveho admina" echo "6. Odstranenie web usera" echo "7. Koniec" read -p "Zadaj cislo: " cislo case $cislo in 1) uninstall_nginx uninstall_php;; 2) install_mariadb ;; 3) add_system_admin ;; 4) add_web_user ;; 5) remove_system_admin ;; 6) remove_web_user ;; 7) zrus=1 ;; *) echo "Zadaj cislo od 1 do 7" ;; esac elif [[ "$(dpkg -l | grep -c mariadb-server)" -gt 0 && "$(dpkg -l | grep -c php)" -gt 0 ]]; then echo "1. Odinstalovanie mariadb, php" echo "2. Nainstalovanie nginx" echo "3. Pridanie systemoveho admina" echo "4. Pridanie web usera" echo "5. Odstranenie systemoveho admina" echo "6. Odstranenie web usera" echo "7. Koniec" read -p "Zadaj cislo: " cislo case $cislo in 1) uninstall_mariadb uninstall_php;; 2) install_nginx ;; 3) add_system_admin ;; 4) add_web_user ;; 5) remove_system_admin ;; 6) remove_web_user ;; 7) zrus=1 ;; *) echo "Zadaj cislo od 1 do 7" ;; esac elif [[ "$(dpkg -l | grep -c nginx)" -gt 0 ]]; then echo "1. Odinstalovanie nginx" echo "2. Nainstalovanie mariadb, php" echo "3. Pridanie systemoveho admina" echo "4. Pridanie web usera" echo "5. Odstranenie systemoveho admina" echo "6. Odstranenie web usera" echo "7. Koniec" read -p "Zadaj cislo: " cislo case $cislo in 1) uninstall_nginx;; 2) install_mariadb install_php ;; 3) add_system_admin ;; 4) add_web_user ;; 5) remove_system_admin ;; 6) remove_web_user ;; 7) zrus=1 ;; *) echo "Zadaj cislo od 1 do 7" ;; esac